package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A change of a plan's amount: the day it was changed on, and the new amount. */
@Embeddable
public class PlanChange {

    @Column(name = "changed_on", nullable = false)
    private LocalDate changedOn;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    protected PlanChange() {
    }

    PlanChange(LocalDate changedOn, BigDecimal amount) {
        this.changedOn = changedOn;
        this.amount = amount;
    }

    public LocalDate getChangedOn() {
        return changedOn;
    }

    public BigDecimal getAmount() {
        return amount;
    }
}
package net.officefloor.hq.app.plan;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class PlanController {

    /**
     * What the screen is told about a plan: its amount with two decimals, its dates (every N days, or a day of
     * the month, the other null), how many claims it has made, its next five dates after the sheet's today, and
     * whether it is paused, and the changes of its amount, oldest first.
     */
    public record PlanView(long id, long personId, String amount, LocalDate start, Integer every, Integer day,
            LocalDate end, int generated, List<LocalDate> nextDates, boolean paused, List<ChangeView> changes) {

        static PlanView of(Plan plan, LocalDate today) {
            return new PlanView(plan.getId(), plan.getPersonId(), plan.getAmount().toPlainString(), plan.getStart(),
                    plan.getEvery(), plan.getDay(), plan.getEnd(), plan.getGenerated(), plan.nextDates(today, 5),
                    plan.isPaused(), plan.getChanges().stream().map(ChangeView::of).toList());
        }
    }

    /** A change of a plan's amount: the day it was changed on, and the new amount with two decimals. */
    public record ChangeView(LocalDate on, String amount) {

        static ChangeView of(PlanChange change) {
            return new ChangeView(change.getChangedOn(), change.getAmount().toPlainString());
        }
    }

    /** A plan's new amount as typed, as the claim form takes it. */
    public record AmountForm(@NotNull @Pattern(regexp = "\\d{1,12}(\\.\\d{1,2})?") String amount) {
    }

    /**
     * A plan as entered on the form: an amount as the claim form takes it, a start, every N days or a day of the
     * month (one of the two, the other absent or blank), and an end.
     */
    public record PlanForm(
            @NotNull @Pattern(regexp = "\\d{1,12}(\\.\\d{1,2})?") String amount,
            @NotNull LocalDate start,
            @Pattern(regexp = "|\\d{1,5}") String every,
            @Pattern(regexp = "|\\d{1,2}") String day,
            @NotNull LocalDate end) {
    }

    /** What a generate made: how many claims, the claims in the order made, and the sheet's plans after it. */
    public record GeneratedView(int count, List<ClaimView> claims, List<PlanView> plans) {
    }

    private final PlanService service;

    public PlanController(PlanService service) {
        this.service = service;
    }

    /** The sheet's plans in the order they were added. */
    @GetMapping("/plans")
    public List<PlanView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId) {
        LocalDate today = service.today(sheetId);
        return service.list(sheetId).stream().map(plan -> PlanView.of(plan, today)).toList();
    }

    /** Add a plan on a person. */
    @PostMapping("/people/{personId}/plans")
    public PlanView add(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PlanForm form) {
        Plan added = service.add(sheetId, SignedIn.name(user), personId, new BigDecimal(form.amount()),
                form.start(), number(form.every()), number(form.day()), form.end());
        return PlanView.of(added, service.today(sheetId));
    }

    /** Pause a plan from the sheet's today; refused when it is paused already. */
    @PostMapping("/plans/{planId}/pause")
    public PlanView pause(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long planId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        return PlanView.of(service.pause(sheetId, SignedIn.name(user), planId, true), service.today(sheetId));
    }

    /** Resume a paused plan on the sheet's today; refused when it is running. */
    @PostMapping("/plans/{planId}/resume")
    public PlanView resume(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long planId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        return PlanView.of(service.pause(sheetId, SignedIn.name(user), planId, false), service.today(sheetId));
    }

    /** Change a plan's amount on the sheet's today; refused for a bad amount. */
    @PostMapping("/plans/{planId}/amount")
    public PlanView amount(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long planId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid AmountForm form) {
        return PlanView.of(service.changeAmount(sheetId, SignedIn.name(user), planId, new BigDecimal(form.amount())),
                service.today(sheetId));
    }

    /** A whole number typed on the form, or null when left out. */
    private static Integer number(String typed) {
        return typed == null || typed.isEmpty() ? null : Integer.valueOf(typed);
    }

    /** Make the claims every plan on the sheet is due up to the sheet's today. */
    @PostMapping("/plans/generate")
    public GeneratedView generate(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        PlanService.Generated generated = service.generate(sheetId, SignedIn.name(user));
        LocalDate today = service.today(sheetId);
        return new GeneratedView(generated.claims().size(), generated.claims().stream().map(ClaimView::of).toList(),
                generated.plans().stream().map(plan -> PlanView.of(plan, today)).toList());
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * A plan on a person: an amount claimed every N days, or monthly on a day of the month, from its start
 * date up to its end date, both included, with the claims it has made so far by the plan date each was made for.
 */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    @Column(name = "start_on", nullable = false)
    private LocalDate start;

    /** Every N days, or null for a monthly plan. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) of a monthly plan, or null for one every N days. */
    @Column(name = "day_of_month")
    private Integer day;

    @Column(name = "end_on", nullable = false)
    private LocalDate end;

    /** The claims the plan has made, by the plan date each was made for. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_claim", joinColumns = @JoinColumn(name = "plan_id"))
    @MapKeyColumn(name = "on_date")
    @Column(name = "claim_id")
    private Map<LocalDate, Long> made = new TreeMap<>();

    /** The plan's pauses, each from the day paused to the day resumed; the last one open while it is paused. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_pause", joinColumns = @JoinColumn(name = "plan_id"))
    private List<PlanPause> pauses = new ArrayList<>();

    /** The changes of the plan's amount, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_change", joinColumns = @JoinColumn(name = "plan_id"))
    @OrderColumn(name = "seq")
    private List<PlanChange> changes = new ArrayList<>();

    protected Plan() {
    }

    public Plan(String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
            Integer day, LocalDate end) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    /**
     * The plan's dates, oldest first, up to its end and the given day: from its start every N days, or for a
     * monthly plan its day in every month from the start's month (the month's last day when the month is
     * shorter), leaving out those before the start and those skipped by a pause.
     */
    public List<LocalDate> datesUpTo(LocalDate today) {
        LocalDate last = today == null || end.isBefore(today) ? end : today;
        List<LocalDate> dates = new ArrayList<>();
        if (day != null) {
            for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
                LocalDate d = month.atDay(Math.min(day, month.lengthOfMonth()));
                if (!d.isBefore(start) && !d.isAfter(last) && !skipped(d)) {
                    dates.add(d);
                }
            }
            return dates;
        }
        for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
            if (!skipped(d)) {
                dates.add(d);
            }
        }
        return dates;
    }

    /** The first count plan dates after the given day, oldest first, on or before the plan's end. */
    public List<LocalDate> nextDates(LocalDate today, int count) {
        return datesUpTo(null).stream().filter(d -> d.isAfter(today)).limit(count).toList();
    }

    /** Whether a pause skips the plan date: on or after the day paused and before the day resumed. */
    private boolean skipped(LocalDate date) {
        return pauses.stream().anyMatch(p -> p.skips(date));
    }

    /** Whether the plan is paused now: its last pause has not been resumed. */
    public boolean isPaused() {
        return !pauses.isEmpty() && pauses.get(pauses.size() - 1).isOpen();
    }

    /** Pause the plan from the day; the caller has checked it is running. */
    public void pause(LocalDate on) {
        pauses.add(new PlanPause(on));
    }

    /** Resume the plan on the day; the caller has checked it is paused. */
    public void resume(LocalDate on) {
        pauses.get(pauses.size() - 1).resume(on);
    }

    /** Change the plan's amount on the day: the claims made from then on take it, those made keep theirs. */
    public void changeAmount(LocalDate on, BigDecimal amount) {
        this.amount = amount;
        changes.add(new PlanChange(on, amount));
    }

    /** The changes of the plan's amount, oldest first. */
    public List<PlanChange> getChanges() {
        return List.copyOf(changes);
    }

    /** Whether the plan has made a claim for the date. */
    public boolean hasMade(LocalDate date) {
        return made.containsKey(date);
    }

    /** Record the claim the plan made for the date. */
    public void made(LocalDate date, long claimId) {
        made.put(date, claimId);
    }

    /** The plan now belongs to another person, as when its person is merged into them. */
    public void moveTo(long personId) {
        this.personId = personId;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    /** Every N days, or null for a monthly plan. */
    public Integer getEvery() {
        return every;
    }

    /** The day of the month of a monthly plan, or null for one every N days. */
    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }

    /** How many claims the plan has made so far. */
    public int getGenerated() {
        return made.size();
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A pause of a plan: the day it was paused, and the day it was resumed, or null while it is still paused. */
@Embeddable
public class PlanPause {

    @Column(name = "paused_on", nullable = false)
    private LocalDate pausedOn;

    @Column(name = "resumed_on")
    private LocalDate resumedOn;

    protected PlanPause() {
    }

    PlanPause(LocalDate pausedOn) {
        this.pausedOn = pausedOn;
    }

    /** Whether the plan date falls on or after the day paused and before the day resumed. */
    boolean skips(LocalDate date) {
        return !date.isBefore(pausedOn) && (resumedOn == null || date.isBefore(resumedOn));
    }

    boolean isOpen() {
        return resumedOn == null;
    }

    void resume(LocalDate on) {
        this.resumedOn = on;
